  const button: ButtonInfo = {
    id: 95000,
    states: (['up', 'over', 'down', 'hit'] as const).map((state, i) => ({
      charId: 95001 + i,
      depth: i + 1,
      matrix: { ...identity, tx: state === 'hit' ? 0 : 200, ty: state === 'hit' ? 0 : 100 },
      color: { mult: [1, 1, 1, state === 'up' ? 0.5 : 1], add: [0, 0, 0, 0] },
      states: {
        up: state === 'up',
        over: state === 'over',
        down: state === 'down',
        hit: state === 'hit',
